"""Original nodule questions: risk, scope and surveillance."""
from qbank_authoring import question,ref,finalize
FN=ref('Fleischner Society: Incidental Pulmonary Nodule Guidelines, 2017','https://pubs.rsna.org/doi/10.1148/radiol.2017161659')
SC=ref('NCI: Lung Cancer Screening—Health Professional PDQ','https://www.cancer.gov/types/lung/hp/lung-screening-pdq')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Which incidental pulmonary-nodule presentation is within the usual scope of Fleischner 2017 guidance?', 'An incidental nodule in an immunocompetent 55-year-old without known cancer',[
 ('A nodule in a patient with active metastatic malignancy','Known cancer requires an individualized oncological assessment.'),('A new nodule in a profoundly immunocompromised patient','Infection and other risks require a different pathway.'),('A nodule detected in an organized lung-cancer screening programme','Screening uses a dedicated framework such as Lung-RADS.')],
 'Apply a guideline only to the population it addresses', '**Fleischner guidance is for selected incidentally detected nodules.**',['It does not routinely apply to patients under 35, immunocompromised patients or patients with cancer.','Screening findings have their own management system.'], '**Establish the context before selecting an interval.**',['Review prior images, symptoms and cancer risk.','A suspicious infectious presentation may need short-term diagnostic assessment rather than routine surveillance.'],[['Incidental eligible adult','Fleischner may apply'],['Known cancer / immunocompromise','Individualized pathway'],['Screening','Dedicated screening framework']],[FN])
q('A low-risk 52-year-old has an incidental solitary solid 4-mm nodule with no suspicious morphology. Under Fleischner 2017 guidance, what is usual management?', 'No routine follow-up CT',[
 ('Immediate surgical resection','That is disproportionate for this low-risk finding.'),('PET-CT every three months','Very small lesions are poorly suited to this strategy.'),('Five years of annual CT for every such solid nodule','This is not the routine low-risk recommendation.')],
 'Very small low-risk solid nodules usually do not need repeated imaging', '**The routine follow-up threshold for solid nodules is generally 6 mm.**',['Suspicious morphology and risk can alter management.','This question specifies a low-risk eligible patient.'], '**Explain the rationale and document the context.**',['Avoid unnecessary radiation and incidental-work-up burden.','Reassess if new symptoms or other information changes the clinical situation.'],[['Size','4 mm'],['Risk','Low with no suspicious feature'],['Usual plan','No routine CT follow-up']],[FN],style='clinical_scenario')
q('A high-risk eligible adult has a solitary incidental solid 7-mm nodule. Which surveillance pattern is consistent with Fleischner guidance?', 'CT at 6–12 months and again at 18–24 months',[
 ('No follow-up for every 7-mm nodule','Risk and size warrant surveillance in this setting.'),('Immediate annual PET for five years','This is not the recommended surveillance pattern.'),('A single chest radiograph in ten years','This does not provide appropriate nodule surveillance.')],
 'Size and risk determine the initial surveillance branch', '**A 6–8-mm solid nodule generally needs interval CT.**',['High-risk patients are usually assessed again at 18–24 months.','Use thin-section technique and comparable measurements.'], '**Modify the plan if growth or suspicious change appears.**',['Surveillance is not permission to ignore progression.','Review prior imaging before starting a new sequence.'],[['Initial interval','6–12 months'],['High-risk second interval','18–24 months'],['Change','Triggers renewed risk assessment']],[FN],style='clinical_scenario')
q('An incidental solid nodule measures 12 mm and has suspicious morphology in a smoker. What is an appropriate management principle?', 'Estimate malignancy probability and consider short-interval CT, PET-CT and/or tissue sampling',[
 ('Use the no-follow-up pathway for all nodules below 20 mm','That ignores the greater-than-8-mm branch and morphology.'),('Assume PET uptake alone proves cancer','Inflammation and infection can also be avid.'),('Ignore prior imaging because only the current diameter matters','Growth and stability are important risk information.')],
 'A larger suspicious nodule needs active risk assessment', '**For nodules greater than 8 mm, options include CT around three months, PET-CT or tissue evaluation.**',['The optimal choice depends on probability and procedural fitness.','Infection prevalence affects PET specificity.'], '**Choose a test that can change the management decision.**',['Discuss biopsy yield and complications.','High-probability lesions in fit patients may require a definitive oncological pathway.'],[['Risk inputs','Size, morphology, growth and patient factors'],['Options','Short-interval CT, PET or tissue'],['Decision','Expected benefit and procedural risk']],[FN],style='clinical_scenario')
q('Why does two-year stability of a persistent subsolid nodule not provide the same reassurance as it often does for a solid nodule?', 'Some subsolid adenocarcinoma-spectrum lesions grow slowly and require longer surveillance',[
 ('Every subsolid nodule is benign after six weeks','Persistence can be clinically important.'),('Subsolid lesions cannot contain invasive cancer','A growing solid component can indicate invasive progression.'),('CT cannot measure a subsolid lesion','Thin-section CT is central to characterization and follow-up.')],
 'Nodule density changes the natural-history question', '**Persistent ground-glass and part-solid lesions can have indolent growth.**',['Fleischner surveillance can extend to five years in relevant subsolid categories.','Transient inflammatory lesions may resolve on early reassessment.'], '**Track the solid component as well as overall size.**',['A new or enlarging solid portion can change risk.','Do not apply a solid-nodule stopping rule indiscriminately.'],[['Solid lesion','Two-year stability can be reassuring in context'],['Subsolid lesion','Longer observation may be needed'],['Solid component','Important progression marker']],[FN])
q('Which change in a persistent part-solid pulmonary nodule is especially concerning?', 'An enlarging solid component',[
 ('Complete disappearance on follow-up','Resolution favors a transient process.'),('A stable typical benign calcification pattern','That is generally reassuring when correctly identified.'),('A smaller overall lesion with no residual suspicious component','That is not the most concerning evolution in this comparison.')],
 'The solid component can reflect invasive progression', '**Follow both total size and the measurable solid portion.**',['A part-solid lesion is not managed solely as a tiny solid nodule.','Thin-section comparable CT technique matters.'], '**Reassess for tissue diagnosis or definitive treatment when risk increases.**',['Consider patient fitness and competing diagnoses.','Use a multidisciplinary pathway for suspicious progression.'],[['Ground-glass portion','May represent a less invasive component'],['Growing solid portion','Greater concern'],['Response','Renewed diagnostic and treatment assessment']],[FN])
q('Which nodule feature most strongly favors a benign hamartoma in the appropriate context?', 'Macroscopic fat with characteristic popcorn-like calcification',[
 ('Spiculated margins with progressive growth','These raise concern for malignancy.'),('An enlarging irregular solid component','This is concerning rather than reassuring.'),('New invasion of an adjacent structure','This suggests aggressive pathology.')],
 'Certain internal features can be more informative than size alone', '**Fat and characteristic chondroid calcification support hamartoma.**',['Not every calcification pattern is benign.','Eccentric or stippled calcification requires contextual assessment.'], '**Confirm the pattern on appropriate CT images.**',['A presumed benign feature should not override discordant growth or symptoms without review.','Use prior imaging and radiological expertise.'],[['Hamartoma clue','Fat and popcorn calcification'],['Concerning features','Spiculation and growth'],['Interpretation','Pattern plus context']],[FN])
q('Which screening test has randomized evidence of reduced lung-cancer mortality in appropriately selected high-risk populations?', 'Low-dose chest CT',[
 ('Annual chest radiography alone','Trials have not established the same mortality benefit.'),('Sputum cytology alone','It is not the supported standalone screening strategy.'),('Routine PET-CT for every asymptomatic adult','This is not an established population screening approach.')],
 'Screening benefit must be demonstrated in outcomes, not only cancer detection', '**LDCT trials have shown a lung-cancer mortality reduction in selected high-risk groups.**',['Eligibility depends on the current screening programme.','False positives, overdiagnosis and radiation are relevant harms.'], '**Use a structured programme with shared decision-making.**',['Screening does not replace smoking cessation.','Symptoms require diagnostic evaluation rather than waiting for a screening appointment.'],[['Supported modality','LDCT'],['Population','Selected high risk'],['Programme','Nodule pathway and harm-benefit discussion']],[SC])
